/* HUD, Tabs, Info Row → common.css \(.page-hud, .game-tab-wrap, .page-info-row\) */
.game-tab-wrap{margin-bottom:10px}
#page-tabs{flex-wrap:nowrap}
#page-tabs .game-tab{min-width:0}

/* ═══ Party Select ═══ */
#section-party{display:flex;flex-direction:column;flex:1;overflow:hidden;align-items:center;width:100%}

/* ── 헤더: 카운터 + 탭 ── */
.ps-header {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-bottom: 12px;
  width: 100%;
  max-width: 330px;
  flex-shrink: 0;
}

.ps-counter {
  font-size: 14px;
  font-weight: 900;
  text-align: center;
  padding: 8px 16px;
  background: rgba\(59,130,246,.08\);
  border: 2px solid rgba\(59,130,246,.3\);
  border-radius: 10px;
  color: var\(--blue\);
  letter-spacing: 1px;
}

.ps-counter.ready {
  background: rgba\(34,197,94,.08\);
  border-color: rgba\(34,197,94,.4\);
  color: var\(--green\);
}

/* 탭 스타일 */
.ps-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}

.ps-tab {
  font-size: 12px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 12px;
  border: 1px solid rgba\(255,255,255,.12\);
  background: rgba\(255,255,255,.04\);
  color: var\(--dim\);
  cursor: pointer;
  transition: all .15s;
  white-space: nowrap;
}

.ps-tab:hover {
  border-color: var\(--blue\);
  color: var\(--text\);
}

.ps-tab.active {
  border-color: var\(--gold\);
  background: rgba\(240,192,64,.12\);
  color: var\(--gold\);
}

/* ── 캐릭터 카드 그리드 ── */
.ps-chars {
  display: grid;
  grid-template-columns: repeat\(2, 1fr\);
  gap: 10px;
  width: 100%;
  max-width: 330px;
  overflow-y: auto;
  flex: 1;
  padding-bottom: 10px;
}

/* PC: 3컬럼 */
@media\(min-width: 1024px\) {
  .ps-chars {
    grid-template-columns: repeat\(3, 1fr\);
    max-width: 660px;
    gap: 12px;
  }

  .ps-header {
    max-width: 660px;
  }
}

/* ── 캐릭터 카드 ── */
.ps-char-card {
  background: rgba\(255,255,255,.04\);
  border: 2px solid rgba\(255,255,255,.08\);
  border-radius: 12px;
  padding: 12px 10px;
  cursor: pointer;
  transition: all .2s;
  display: flex;
  flex-direction: column;
  gap: 8px;
  align-items: center;
  position: relative;
}

.ps-char-card:hover {
  border-color: rgba\(96,165,250,.4\);
  background: rgba\(96,165,250,.06\);
  transform: translateY\(-2px\);
  box-shadow: 0 4px 12px rgba\(96,165,250,.2\);
}

/* 파티 선택됨 */
.ps-char-card.in-party {
  background: rgba\(240,192,64,.08\);
  border-color: rgba\(240,192,64,.5\);
}

.ps-char-card.in-party:hover {
  background: rgba\(240,192,64,.12\);
  border-color: rgba\(240,192,64,.7\);
}

/* ── 파티 배지 ── */
.ps-party-badge {
  position: absolute;
  top: 8px;
  right: 8px;
  background: linear-gradient\(135deg, #f59e0b, #d97706\);
  color: #fff;
  font-size: 10px;
  font-weight: 900;
  padding: 3px 8px;
  border-radius: 12px;
  box-shadow: 0 2px 6px rgba\(245,158,11,.4\);
  display: flex;
  align-items: center;
  gap: 3px;
}

/* ── 캐릭터 아이콘 + 등급 ── */
.ps-char-icon {
  width: 60px;
  height: 60px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}

.ps-char-icon img,
.ps-char-icon svg {
  width: 60px;
  height: 60px;
  object-fit: contain;
}

.ps-grade-badge {
  position: absolute;
  bottom: -2px;
  left: -2px;
  font-size: 9px;
  font-weight: 900;
  width: 16px;
  height: 16px;
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba\(0,0,0,.7\);
  border: 1px solid;
}

/* ── 캐릭터 정보 ── */
.ps-char-info {
  text-align: center;
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.ps-char-meta {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  font-size: 10px;
  color: var\(--dim\);
}

.ps-char-level {
  font-weight: 700;
  color: var\(--text\);
}

.ps-char-cls {
  color: var\(--text\);
}

.ps-char-name {
  font-size: 12px;
  font-weight: 900;
  color: var\(--text\);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
}

.ps-rename-btn {
  background: none;
  border: none;
  color: var\(--dim\);
  font-size: 12px;
  padding: 0;
  cursor: pointer;
  flex-shrink: 0;
  opacity: .6;
  transition: opacity .15s;
}

.ps-rename-btn:hover {
  opacity: 1;
  color: var\(--blue\);
}

/* ── 스탯 \(콤팩트\) ── */
.ps-char-stats {
  font-size: 10px;
  color: var\(--dim\);
  display: flex;
  flex-wrap: wrap;
  gap: 2px 8px;
  justify-content: center;
  line-height: 1.3;
}

.ps-char-stats b {
  color: var\(--text\);
}

.ps-char-stats .eq-bonus {
  color: #4ade80;
  font-size: 9px;
}

/* ── 잠재력 ── */
.ps-char-potential {
  font-size: 9px;
  color: #64748b;
  text-align: center;
}

/* ── EXP 바 ── */
.ps-char-exp {
  height: 3px;
  background: rgba\(255,255,255,.08\);
  border-radius: 2px;
  overflow: hidden;
  width: 100%;
}

.ps-char-exp-fill {
  height: 100%;
  background: linear-gradient\(90deg, #a78bfa, #7c3aed\);
  border-radius: 2px;
  transition: width .3s;
}

/* ── 스킬 정보 ── */
.ps-char-skills {
  font-size: 9px;
  color: var\(--text\);
  text-align: center;
  line-height: 1.3;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  width: 100%;
}

/* ── 방출 버튼 \(카드 하단\) ── */
.ps-release-btn {
  font-size: 10px;
  padding: 4px 12px;
  border: none;
  border-radius: 6px;
  background: linear-gradient\(135deg, #ef4444, #dc2626\);
  color: #fff;
  font-weight: 700;
  cursor: pointer;
  transition: all .15s;
  width: 100%;
  margin-top: 4px;
}

.ps-release-btn:hover {
  transform: scale\(1.05\);
  box-shadow: 0 2px 6px rgba\(239,68,68,.4\);
}

.ps-release-btn:active {
  transform: scale\(.95\);
}

/* 파티원은 방출 버튼 숨김 */
.ps-char-card.in-party .ps-release-btn {
  display: none;
}

/* ── 출격 버튼 ── */
.ps-start {
  font-family: 'Cinzel', serif;
  font-weight: 900;
  font-size: 15px;
  background: linear-gradient\(135deg, var\(--gold\), #d4a017\);
  color: #1a1a2e;
  border: none;
  padding: 10px 32px;
  border-radius: 10px;
  cursor: pointer;
  text-transform: uppercase;
  letter-spacing: 2px;
  transition: all .2s;
  margin-top: 10px;
  flex-shrink: 0;
  width: 100%;
  max-width: 330px;
}

.ps-start:hover {
  transform: scale\(1.05\);
}

.ps-start:disabled {
  opacity: .3;
  cursor: default;
  transform: none;
}

/* ═══ Potion Use Modal ═══ */
.potion-target-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
  max-height: 200px;
  overflow-y: auto;
  margin-top: 4px;
}

.pt-btn {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 10px;
  border-radius: 8px;
  background: rgba\(255,255,255,.06\);
  border: 1px solid rgba\(255,255,255,.1\);
  cursor: pointer;
  transition: all .15s;
}

.pt-btn:hover {
  border-color: var\(--gold\);
  background: rgba\(240,192,64,.08\);
}

.pt-icon {
  font-size: 18px;
}

.pt-info {
  flex: 1;
  font-size: 11px;
  font-weight: 700;
  text-align: left;
}

.pt-exp {
  font-size: 9px;
  color: #a78bfa;
}

/* ═══ Item Tab ═══ */
#section-item {
  display: flex;
  flex-direction: column;
  flex: 1;
  overflow: hidden;
  align-items: center;
  width: 100%;
}

.item-list {
