  flex-shrink: 0;
}

.item-use-btn:hover {
  transform: scale\(1.05\);
  box-shadow: 0 2px 6px rgba\(167,139,250,.4\);
}

.item-use-btn:active {
  transform: scale\(.95\);
}

/* ═══ PC \(1024px+\) ═══ */
@media\(min-width: 1024px\) {
  .ps-counter {
    font-size: 16px;
    padding: 10px 20px;
  }

  .ps-tab {
    font-size: 13px;
