.enhance-modal-btn:hover {
  background: rgba\(255,255,255,.08\);
  border-color: rgba\(255,255,255,.2\);
}

.enhance-modal-btn.primary {
  background: rgba\(96,165,250,.2\);
  border-color: rgba\(96,165,250,.4\);
  color: var\(--blue\);
}

.enhance-modal-btn.primary:hover {
  background: rgba\(96,165,250,.3\);
  border-color: rgba\(96,165,250,.6\);
}

/* ═══ Inventory Tab ═══ */
#section-inventory {
  display: flex;
  flex-direction: column;
  flex: 1;
  overflow: hidden;
  align-items: center;
  width: 100%;
}

.inv-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  flex: 1;
  overflow: hidden;
  width: 100%;
  max-width: 330px;
}

.inv-stats {
  width: 100%;
  max-width: 330px;
  margin-bottom: 8px;
}

.inv-filters {
  width: 100%;
  max-width: 330px;
  margin-bottom: 8px;
}

.inv-filter-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-bottom: 8px;
}

.inv-filter-row {
  display: flex;
  gap: 8px;
}

.inv-filter-dropdown,
.inv-sort-dropdown {
  flex: 1;
  padding: 8px 12px;
  font-size: 11px;
  font-weight: 700;
  background: rgba\(255,255,255,.04\);
  border: 1px solid rgba\(255,255,255,.12\);
  border-radius: 6px;
  color: var\(--text\);
  cursor: pointer;
}

.inv-filter-dropdown:focus,
.inv-sort-dropdown:focus {
  outline: none;
  border-color: var\(--blue\);
}

.inv-grid {
  width: 100%;
  max-width: 330px;
  display: grid;
  grid-template-columns: repeat\(2, 1fr\);
  gap: 10px;
  overflow-y: auto;
  flex: 1;
  padding: 0 4px;
}

.inv-card {
  position: relative;
  background: rgba\(255,255,255,.04\);
  border: 1px solid rgba\(255,255,255,.08\);
  border-radius: 10px;
  padding: 12px;
  transition: all .15s;
}

.inv-card:hover {
  border-color: rgba\(255,255,255,.15\);
  background: rgba\(255,255,255,.06\);
  transform: translateY\(-2px\);
}

.inv-card-header {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 6px;
}

.inv-card-icon {
  font-size: 28px;
  flex-shrink: 0;
}

.inv-card-name {
  font-weight: 700;
  font-size: 13px;
  color: var\(--text\);
  flex: 1;
}

.inv-card-rarity {
  height: 3px;
  border-radius: 2px;
  margin: 6px 0;
}

.inv-card-rarity-text {
  font-size: 11px;
  font-weight: 700;
  margin-bottom: 4px;
}

.inv-card-stats {
  font-size: 12px;
  color: var\(--dim\);
  margin-bottom: 6px;
}

.inv-card-effect {
  font-size: 12px;
  color: #a78bfa;
  margin-bottom: 6px;
}

.inv-enhance-badge {
  position: absolute;
  top: 8px;
  right: 8px;
  font-size: 11px;
  font-weight: 900;
  padding: 3px 7px;
  border-radius: 12px;
  background: rgba\(0,0,0,.6\);
  border: 1px solid;
}

.inv-enhance-badge.low {
  color: #4ade80;
  border-color: #4ade80;
}

.inv-enhance-badge.mid {
  color: #60a5fa;
  border-color: #60a5fa;
}

.inv-enhance-badge.high {
  color: #f0c040;
  border-color: #f0c040;
}

.inv-equipped-badge {
  position: absolute;
  bottom: 8px;
  right: 8px;
  font-size: 9px;
  font-weight: 700;
  padding: 3px 7px;
  border-radius: 10px;
  background: rgba\(96,165,250,.2\);
  border: 1px solid #60a5fa;
  color: #60a5fa;
}

.inv-count-badge {
  position: absolute;
  top: 8px;
  right: 8px;
  font-size: 13px;
  font-weight: 900;
  padding: 4px 10px;
  border-radius: 14px;
  background: rgba\(240,192,64,.15\);
  border: 1px solid #f0c040;
  color: #f0c040;
}

.inv-card-actions {
  display: flex;
  gap: 6px;
  margin-top: 8px;
}

.inv-btn-equip,
.inv-btn-use,
.inv-btn-sell {
  flex: 1;
  font-size: 11px;
  font-weight: 700;
  padding: 6px 10px;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  transition: all .15s;
}

.inv-btn-equip {
  background: linear-gradient\(135deg, #60a5fa, #3b82f6\);
  color: #fff;
}

.inv-btn-use {
  background: linear-gradient\(135deg, #a78bfa, #7c3aed\);
  color: #fff;
}

.inv-btn-sell {
  background: linear-gradient\(135deg, #4ade80, #22c55e\);
  color: #fff;
}

.inv-btn-equip:hover,
.inv-btn-use:hover,
.inv-btn-sell:hover {
  transform: scale\(1.05\);
}

.inv-empty {
  text-align: center;
  padding: 60px 20px;
}

.inv-empty-icon {
  font-size: 64px;
  margin-bottom: 16px;
  opacity: .3;
}

.inv-empty-text {
  font-size: 14px;
  color: var\(--dim\);
}

@media\(min-width: 1024px\) {
  .inv-container {
    max-width: 660px;
  }

  .inv-stats {
    max-width: 660px;
  }

  .inv-filters {
    max-width: 660px;
  }

  .inv-grid {
    max-width: 660px;
    display: grid;
    grid-template-columns: repeat\(4, 1fr\);
    gap: 12px;
  }

  .inv-card {
    padding: 10px;
  }

  .inv-card-icon {
    font-size: 24px;
  }

  .inv-card-name {
    font-size: 11px;
  }

  .inv-card-rarity-text {
    font-size: 9px;
  }

  .inv-card-stats {
    font-size: 10px;
  }

  .inv-card-effect {
    font-size: 10px;
  }
}
